def transform(grid):
    if not grid or not grid[0]:
        return grid

    # Find background color (most frequent)
    color_counts = {}
    for r in grid:
        for c in r:
            color_counts[c] = color_counts.get(c, 0) + 1
    bg = max(color_counts, key=color_counts.get)

    height = len(grid)
    width = len(grid[0])

    # Count non-bg pixels per column
    col_scores = []
    for c in range(width):
        score = sum(1 for r in range(height) if grid[r][c] != bg)
        col_scores.append((c, score))

    # Sort by score descending, then by column index
    col_scores.sort(key=lambda x: (-x[1], x[0]))

    # Target output width - varies based on data, seems around 40-60% of original
    target_width = int(width * 0.4) if width > 5 else 3

    # Take top columns
    selected_cols = [c for c, _ in col_scores[:target_width]]

    # Ensure we have at least the first few columns for structural integrity
    if selected_cols and len(selected_cols) < 3:
        # Keep some initial columns
        for c in range(width):
            if c >= target_width and c not in selected_cols:
                selected_cols.append(c)
            if len(selected_cols) >= max(3, target_width):
                break

    # Build output
    output = []
    for r in range(height):
        row_out = [grid[r][c] for c in selected_cols]
        output.append(row_out)

    return output
