from collections import Counter

def transform(grid):
    if not grid or not grid[0]:
        return grid

    # Find background color (most frequent)
    color_counts = Counter()
    for row in grid:
        for cell in row:
            color_counts[cell] += 1

    bg = max(color_counts, key=color_counts.get)

    # Find foreground colors and their frequencies
    fg_counts = {c: color_counts[c] for c in color_counts if c != bg}
    if not fg_counts:
        return grid

    # Remove the least frequent foreground color
    least_fg = min(fg_counts, key=fg_counts.get)

    # Replace least frequent FG color with BG
    modified_grid = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == least_fg:
                new_row.append(bg)
            else:
                new_row.append(cell)
        modified_grid.append(new_row)

    height = len(modified_grid)
    width = len(modified_grid[0])

    # Find columns containing any foreground content (non-BG)
    keep_cols = []
    for c in range(width):
        if any(modified_grid[r][c] != bg for r in range(height)):
            keep_cols.append(c)

    # Build output with only selected columns
    output = [[modified_grid[r][c] for c in keep_cols] for r in range(height)]

    return output
